-- Fix invalid StateId references
UPDATE Cities
SET StateId = NULL
WHERE StateId IS NOT NULL
AND StateId NOT IN (SELECT StateId FROM States);

ALTER TABLE Cities WITH CHECK CHECK CONSTRAINT FK_Cities_States_StateId;

SET IDENTITY_INSERT Cities OFF;